    "explanation": "【解】因为 $B$ 是 $3$ 阶正交矩阵，所以 $B B^T = E$，且 $|B|^2 = 1$。又 $|B| < 0$，故 $|B| = -1$。利用 $E = B B^T$ 进行恒等变形：$$|E - B A^T| = |B B^T - B A^T| = |B(B^T - A^T)| = |B| \\cdot |(B - A)^T| = |B| \\cdot |B - A|$$因为 $A, B$ 为 $3$ 阶矩阵，所以 $|B - A| = |-(A - B)| = (-1)^3 |A - B| = -6$。因此 $|E - BA^T| = (-1) \\times (-6) = 6$。",
    "steps": [
      "由 $B$ 为 $3$ 阶正交矩阵且 $|B| < 0$，确定 $B B^T = E$ 及 $|B| = -1$。",
      "将 $E$ 替换为 $B B^T$ 并提取左因子 $B$：$|E - B A^T| = |B| \\cdot |B^T - A^T|$。",
      "结合转置不变性与 $3$ 阶提取负号规律 $|B - A| = (-1)^3 |A - B| = -6$，求得结果为 $6$。"
    ],
