    "question": "【线代救命讲义·1.24】设 $A$ 是 $3$ 阶矩阵，将 $A$ 的第 $1, 2$ 行互换得矩阵 $B$，再将 $B$ 的第 $2, 3$ 列互换得单位矩阵，记 $P_1 = \\begin{pmatrix} 0 & 1 & 0 \\\\ 1 & 0 & 0 \\\\ 0 & 0 & 1 \\end{pmatrix}, P_2 = \\begin{pmatrix} 1 & 0 & 0 \\\\ 0 & 0 & 1 \\\\ 0 & 1 & 0 \\end{pmatrix}$，则 $A^* = (\\quad)$。",
