    "question": "【线代救命讲义·2.11】设向量组 $\\alpha_1 = [1, 1, 1, 3]^T$，$\\alpha_2 = [-1, -3, 5, 1]^T$，$\\alpha_3 = [3, 2, -1, p+2]^T$，$\\alpha_4 = [-2, -6, 10, p]^T$。\n（1）$p$ 为何值时，该向量组线性无关？并在此时将向量 $\\alpha = [4, 1, 6, 10]^T$ 用 $\\alpha_1, \\alpha_2, \\alpha_3, \\alpha_4$ 线性表示；\n（2）$p$ 为何值时，该向量组线性相关？并在此时求出它的秩和一个极大线性无关组。",
