    "explanation": "【解】以 $\\alpha_1, \\alpha_2, \\alpha_3, \\alpha_4$ 为列构造矩阵 $A$ 并拼接 $\\alpha$ 作增广矩阵 $(A \\mid \\alpha)$，进行初等行变换：$$\\begin{bmatrix} 1 & -1 & 3 & -2 & 4 \\\\ 1 & -3 & 2 & -6 & 1 \\\\ 1 & 5 & -1 & 10 & 6 \\\\ 3 & 1 & p+2 & p & 10 \\end{bmatrix} \\xrightarrow{\\substack{r_2-r_1, r_3-r_1 \\\\ r_4-3r_1}} \\begin{bmatrix} 1 & -1 & 3 & -2 & 4 \\\\ 0 & -2 & -1 & -4 & -3 \\\\ 0 & 6 & -4 & 12 & 2 \\\\ 0 & 4 & p-7 & p+6 & -2 \\end{bmatrix} \\xrightarrow{\\substack{r_3+3r_2 \\\\ r_4+2r_2}} \\begin{bmatrix} 1 & -1 & 3 & -2 & 4 \\\\ 0 & -2 & -1 & -4 & -3 \\\\ 0 & 0 & -7 & 0 & -7 \\\\ 0 & 0 & p-9 & p-2 & -8 \\end{bmatrix}$$将第 $3$ 行除以 $-7$ 后消第 $4$ 行第 $3$ 列（$r_4 - (p-9)r_3$），得阶梯形：$$\\begin{bmatrix} 1 & -1 & 3 & -2 & 4 \\\\ 0 & -2 & -1 & -4 & -3 \\\\ 0 & 0 & 1 & 0 & 1 \\\\ 0 & 0 & 0 & p-2 & 1-p \\end{bmatrix}$$\n（1）当 $p - 2 \\neq 0$ 即 $p \\neq 2$ 时，$r(A) = 4$，向量组 $\\alpha_1, \\alpha_2, \\alpha_3, \\alpha_4$ 线性无关。由行阶梯形回代求解非齐次方程组 $Ax = \\alpha$：由第 $4$ 行得 $x_4 = \\frac{1-p}{p-2}$；由第 $3$ 行得 $x_3 = 1$；代入第 $2$ 行得 $-2x_2 - 1 - 4\\frac{1-p}{p-2} = -3 \\implies -2x_2 = \\frac{8-6p}{p-2} \\implies x_2 = \\frac{3p-4}{p-2}$；代入第 $1$ 行得 $x_1 = 4 - 3 + \\frac{3p-4}{p-2} + 2\\frac{1-p}{p-2} = 1 + 1 = 2$。故：$$\\alpha = 2\\alpha_1 + \\frac{3p-4}{p-2}\\alpha_2 + \\alpha_3 + \\frac{1-p}{p-2}\\alpha_4$$\n（2）当 $p = 2$ 时，$r(A) = 3 < 4$，向量组线性相关，且秩为 $3$。阶梯形前 $3$ 列为主元列，故一个极大线性无关组为 $\\alpha_1, \\alpha_2, \\alpha_3$（因 $p=2$ 时 $\\alpha_4 = 2\\alpha_2$）。",
