    "explanation": "【解】方法一（线性方程组解的视角）：设 $A$ 为 $m \\times n$ 矩阵，$B$ 为 $n \\times s$ 矩阵。因 $AB = O$ 且 $B \\neq O$，$B$ 至少有一个非零列向量 $\\beta_j$ 满足 $A\\beta_j = 0$，即齐次线性方程组 $Ax = 0$ 有非零解，因此 $A$ 的**列向量组**必线性相关！\n同理，两边转置得 $B^T A^T = O$，且 $A^T \\neq O$，故 $B^T$ 的列向量组线性相关，即 $B$ 的**行向量组**必线性相关！\n方法二（零积秩公式视角）：由 $AB = O$ 且 $r(A) \\ge 1, r(B) \\ge 1$，得 $r(A) + r(B) \\le n$，故 $r(A) < n$（$A$ 列不满秩，列向量组线性相关）且 $r(B) < n$（$B$ 行不满秩，行向量组线性相关）。故选 A。",
    "steps": [
      "将 $AB = O$ 按列分块，由于 $B \\neq O$，说明 $Ax = 0$ 有非零解，推出 $A$ 的列向量组线性相关。",
      "对 $AB = O$ 取转置得 $B^T A^T = O$，同理推出 $B$ 的行向量组线性相关（或直接由 $r(A)<n, r(B)<n$ 判定）。"
    ],
