    "explanation": "（1）由 $A^2 = A$ 得 $A(A - E) = O$，从而 $r(A) + r(A - E) \\le n$。另一方面，由秩的次可加性，$n = r(E) = r(A + (E - A)) \\le r(A) + r(E - A) = r(A) + r(A - E)$。两式结合得 $r(A) + r(A - E) = n$，即 $[n - r(A)] + [n - r(E - A)] = n$。因为 $A$ 的特征值只能满足 $\\lambda^2 = \\lambda$，即 $\\lambda = 0$ 或 $\\lambda = 1$，而属于 $\\lambda = 0$ 与 $\\lambda = 1$ 的线性无关特征向量个数之和为 $[n - r(A)] + [n - r(E - A)] = n$，故 $A$ 有 $n$ 个线性无关的特征向量，从而可相似对角化。\n（2）因 $A$ 可相似对角化且 $r(A) = r$，故 $A$ 有 $r$ 个特征值为 $1$，其余 $n - r$ 个特征值为 $0$。从而 $3E - A$ 的特征值为 $r$ 个 $2$ 和 $n - r$ 个 $3$，故 $|3E - A| = 2^r \\cdot 3^{n-r}$。",
    "steps": [
      "由 $A(A-E)=O$ 与 $E = A + (E-A)$ 夹逼得出 $r(A) + r(E-A) = n$。",
      "将其转化为 $\\lambda=0$ 与 $\\lambda=1$ 特征向量总数等于 $n$，证毕可对角化。",
      "由 $r(A)=r$ 确定特征值 $1$ 有 $r$ 个、$0$ 有 $n-r$ 个，进而求得 $|3E - A|$。"
    ],
