    "explanation": "先求（2）：由 $A^3\\boldsymbol{\\alpha} = 3A\\boldsymbol{\\alpha} - 2A^2\\boldsymbol{\\alpha}$，得 $AP = (A\\boldsymbol{\\alpha}, A^2\\boldsymbol{\\alpha}, A^3\\boldsymbol{\\alpha}) = (\\boldsymbol{\\alpha}, A\\boldsymbol{\\alpha}, A^2\\boldsymbol{\\alpha}) \\begin{pmatrix} 0 & 0 & 0 \\\\ 1 & 0 & 3 \\\\ 0 & 1 & -2 \\end{pmatrix} = PB$。因 $\\boldsymbol{\\alpha}, A\\boldsymbol{\\alpha}, A^2\\boldsymbol{\\alpha}$ 线性无关，故 $P$ 可逆，$P^{-1}AP = B = \\begin{pmatrix} 0 & 0 & 0 \\\\ 1 & 0 & 3 \\\\ 0 & 1 & -2 \\end{pmatrix}$。\n（1）$A \\sim B$，求 $B$ 的特征值：$|\\lambda E - B| = \\begin{vmatrix} \\lambda & 0 & 0 \\\\ -1 & \\lambda & -3 \\\\ 0 & -1 & \\lambda+2 \\end{vmatrix} = \\lambda(\\lambda^2 + 2\\lambda - 3) = \\lambda(\\lambda - 1)(\\lambda + 3) = 0$，得特征值 $\\lambda_1 = 0, \\lambda_2 = 1, \\lambda_3 = -3$。分别解 $(\\lambda_i E - B)\\boldsymbol{\\eta}_i = \\boldsymbol{0}$ 得 $B$ 的特征向量 $\\boldsymbol{\\eta}_1 = (-3, 2, 1)^T$，$\\boldsymbol{\\eta}_2 = (0, 3, 1)^T$，$\\boldsymbol{\\eta}_3 = (0, -1, 1)^T$。再由 $\\boldsymbol{\\xi}_i = P\\boldsymbol{\\eta}_i$ 得 $A$ 对应的全部特征向量分别为：$k_1(-3\\boldsymbol{\\alpha} + 2A\\boldsymbol{\\alpha} + A^2\\boldsymbol{\\alpha})$，$k_2(3A\\boldsymbol{\\alpha} + A^2\\boldsymbol{\\alpha})$，$k_3(-A\\boldsymbol{\\alpha} + A^2\\boldsymbol{\\alpha})$（$k_1, k_2, k_3 \\neq 0$）。\n最后 $|A + E| = (0 + 1)(1 + 1)(-3 + 1) = -4$。",
