    "question": "设 $\\boldsymbol{\\alpha}_1, \\boldsymbol{\\alpha}_2, \\boldsymbol{\\alpha}_3$ 是线性无关的 $3$ 维列向量组，$A$ 为 $3$ 阶矩阵。已知 $A\\boldsymbol{\\alpha}_1 = a\\boldsymbol{\\alpha}_1 + \\boldsymbol{\\alpha}_2 + \\boldsymbol{\\alpha}_3$，$A\\boldsymbol{\\alpha}_2 = b\\boldsymbol{\\alpha}_2 - 2\\boldsymbol{\\alpha}_3$，$A\\boldsymbol{\\alpha}_3 = -2\\boldsymbol{\\alpha}_2 + (a - b)\\boldsymbol{\\alpha}_3$。已知存在可逆矩阵 $P$ 使得 $P^{-1}AP = \\begin{pmatrix} -1 & 0 & 0 \\\\ 0 & 2 & 0 \\\\ 0 & 0 & 3 \\end{pmatrix}$。\n（1）求 $a, b$；\n（2）用 $\\boldsymbol{\\alpha}_1, \\boldsymbol{\\alpha}_2, \\boldsymbol{\\alpha}_3$ 表示所有满足要求的可逆矩阵 $P$。",
