    "explanation": "（1）令 $M = (\\boldsymbol{\\alpha}_1, \\boldsymbol{\\alpha}_2, \\boldsymbol{\\alpha}_3)$，由已知线性无关知 $M$ 可逆，且 $AM = MC$，其中 $C = \\begin{pmatrix} a & 0 & 0 \\\\ 1 & b & -2 \\\\ 1 & -2 & a - b \\end{pmatrix}$。由 $M^{-1}AM = C \\sim \\mathrm{diag}(-1, 2, 3)$ 知 $C$ 的特征值为 $-1, 2, 3$。首先 $\\mathrm{tr}(C) = a + b + (a - b) = 2a = -1 + 2 + 3 = 4 \\Rightarrow a = 2$。再计算 $|\\lambda E - C| = (\\lambda - 2)[(\\lambda - b)(\\lambda - 2 + b) - 4] = 0$，另两根 $-1, 3$ 之积为 $b(2 - b) - 4 = -3 \\Rightarrow b^2 - 2b + 1 = 0 \\Rightarrow b = 1$。\n（2）当 $a=2, b=1$ 时，$C = \\begin{pmatrix} 2 & 0 & 0 \\\\ 1 & 1 & -2 \\\\ 1 & -2 & 1 \\end{pmatrix}$。分别求 $C$ 对应 $\\lambda_1 = -1, \\lambda_2 = 2, \\lambda_3 = 3$ 的特征向量：$(-E - C)\\boldsymbol{\\xi}_1 = \\boldsymbol{0} \\Rightarrow \\boldsymbol{\\xi}_1 = (0, 1, 1)^T$；$(2E - C)\\boldsymbol{\\xi}_2 = \\boldsymbol{0} \\Rightarrow \\boldsymbol{\\xi}_2 = (3, 1, 1)^T$；$(3E - C)\\boldsymbol{\\xi}_3 = \\boldsymbol{0} \\Rightarrow \\boldsymbol{\\xi}_3 = (0, 1, -1)^T$。因此 $A$ 对应特征向量为 $M\\boldsymbol{\\xi}_i$，所有满足要求的可逆矩阵为 $P = \\big(k_1(\\boldsymbol{\\alpha}_2 + \\boldsymbol{\\alpha}_3),\\ k_2(3\\boldsymbol{\\alpha}_1 + \\boldsymbol{\\alpha}_2 + \\boldsymbol{\\alpha}_3),\\ k_3(\\boldsymbol{\\alpha}_2 - \\boldsymbol{\\alpha}_3)\\big)$（$k_1, k_2, k_3 \\neq 0$）。",
