    "question": "（本题满分 12 分）设 $A = \\begin{pmatrix} 3 & 2 & -2 \\\\ -a & -1 & a \\\\ 4 & 2 & -3 \\end{pmatrix}$ 有三个线性无关的特征向量。\n（I）求 $a$ 的值，并求可逆矩阵 $P$，使 $P^{-1}AP = \\Lambda$；\n（II）求可逆的实对称矩阵 $Q$，使 $Q^{-1}AQ = A^T$。",
    "correctAnswer": "（I）$a = 0$，$P = \\begin{pmatrix} 1 & 1 & 0 \\\\ 0 & -2 & 1 \\\\ 1 & 0 & 1 \\end{pmatrix}$，$\\Lambda = \\begin{pmatrix} 1 & 0 & 0 \\\\ 0 & -1 & 0 \\\\ 0 & 0 & -1 \\end{pmatrix}$；（II）$Q = \\begin{pmatrix} 2 & -2 & 1 \\\\ -2 & 5 & 1 \\\\ 1 & 1 & 2 \\end{pmatrix}$（不唯一）",
    "explanation": "（I）计算特征多项式：$$|\\lambda E - A| = \\begin{vmatrix} \\lambda - 3 & -2 & 2 \\\\ a & \\lambda + 1 & -a \\\\ -4 & -2 & \\lambda + 3 \\end{vmatrix} \\xrightarrow{c_1 + c_3} (\\lambda - 1)\\begin{vmatrix} 1 & -2 & 2 \\\\ 0 & \\lambda + 1 & -a \\\\ 1 & -2 & \\lambda + 3 \\end{vmatrix} = (\\lambda - 1)(\\lambda + 1)^2.$$ 故特征值为 $\\lambda_1 = 1, \\lambda_2 = \\lambda_3 = -1$。因为 $A$ 有三个线性无关的特征向量，所以 $r(-E - A) = 1$。而 $-E - A = \\begin{pmatrix} -4 & -2 & 2 \\\\ a & 0 & -a \\\\ -4 & -2 & 2 \\end{pmatrix}$，要使其秩为 $1$ 必有 $a = 0$。当 $a = 0$ 时，解 $(E - A)\\boldsymbol{x} = \\boldsymbol{0}$ 得 $\\boldsymbol{\\xi}_1 = (1, 0, 1)^T$；解 $(-E - A)\\boldsymbol{x} = \\boldsymbol{0}$ 得 $\\boldsymbol{\\xi}_2 = (1, -2, 0)^T, \\boldsymbol{\\xi}_3 = (0, 1, 1)^T$。于是 $P = \\begin{pmatrix} 1 & 1 & 0 \\\\ 0 & -2 & 1 \\\\ 1 & 0 & 1 \\end{pmatrix}$，$\\Lambda = \\begin{pmatrix} 1 & 0 & 0 \\\\ 0 & -1 & 0 \\\\ 0 & 0 & -1 \\end{pmatrix}$。\n（II）由 $P^{-1}AP = \\Lambda$ 两边取转置得 $P^T A^T (P^T)^{-1} = \\Lambda$，即 $A^T = (P^T)^{-1} \\Lambda P^T$。代入 $A = P\\Lambda P^{-1}$ 得 $Q^{-1}P\\Lambda P^{-1}Q = (P^T)^{-1}\\Lambda P^T$，令 $P^{-1}Q = P^T$，即取 $Q = P P^T$。显然 $Q$ 可逆且 $Q^T = (P P^T)^T = P P^T = Q$ 为实对称矩阵。计算得 $Q = \\begin{pmatrix} 1 & 1 & 0 \\\\ 0 & -2 & 1 \\\\ 1 & 0 & 1 \\end{pmatrix}\\begin{pmatrix} 1 & 0 & 1 \\\\ 1 & -2 & 0 \\\\ 0 & 1 & 1 \\end{pmatrix} = \\begin{pmatrix} 2 & -2 & 1 \\\\ -2 & 5 & 1 \\\\ 1 & 1 & 2 \\end{pmatrix}$。",
