    "question": "设 $\\boldsymbol{\\alpha}, \\boldsymbol{\\beta}$ 是 $3$ 维单位正交列向量组，$A = \\boldsymbol{\\alpha}\\boldsymbol{\\beta}^T + \\boldsymbol{\\beta}\\boldsymbol{\\alpha}^T$。\n（1）证明 $A$ 可相似对角化；\n（2）若 $\\boldsymbol{\\alpha} = \\left[\\dfrac{\\sqrt{2}}{2}, 0, \\dfrac{\\sqrt{2}}{2}\\right]^T$，$\\boldsymbol{\\beta} = [0, 1, 0]^T$，求方程组 $A^*\\boldsymbol{x} = \\boldsymbol{0}$ 的全部解；\n（3）若 $\\boldsymbol{\\alpha} = \\left[\\dfrac{\\sqrt{2}}{2}, 0, \\dfrac{\\sqrt{2}}{2}\\right]^T$，$\\boldsymbol{\\beta} = [0, 1, 0]^T$，求正交矩阵 $C$，使得 $C^T(A + A^*)C$ 为对角矩阵，并求此对角矩阵。",
    "correctAnswer": "（1）$A^T = A$ 为实对称矩阵故可对角化；（2）$\\boldsymbol{x} = k_1(1,0,1)^T + k_2(0,1,0)^T$（$k_1,k_2$ 任意）；（3）$C = \\begin{pmatrix} \\frac{1}{2} & \\frac{1}{2} & \\frac{\\sqrt{2}}{2} \\\\ \\frac{\\sqrt{2}}{2} & -\\frac{\\sqrt{2}}{2} & 0 \\\\ \\frac{1}{2} & \\frac{1}{2} & -\\frac{\\sqrt{2}}{2} \\end{pmatrix}$，对角矩阵为 $\\mathrm{diag}(1, -1, -1)$",
    "explanation": "（1）$A^T = (\\boldsymbol{\\alpha}\\boldsymbol{\\beta}^T + \\boldsymbol{\\beta}\\boldsymbol{\\alpha}^T)^T = \\boldsymbol{\\beta}\\boldsymbol{\\alpha}^T + \\boldsymbol{\\alpha}\\boldsymbol{\\beta}^T = A$，故 $A$ 是实对称矩阵，因此 $A$ 必可相似对角化。\n（2）代入 $\\boldsymbol{\\alpha}, \\boldsymbol{\\beta}$ 算得 $A = \\begin{pmatrix} 0 & \\frac{\\sqrt{2}}{2} & 0 \\\\ \\frac{\\sqrt{2}}{2} & 0 & \\frac{\\sqrt{2}}{2} \\\\ 0 & \\frac{\\sqrt{2}}{2} & 0 \\end{pmatrix}$，求其伴随矩阵 $A^* = \\begin{pmatrix} -\\frac{1}{2} & 0 & \\frac{1}{2} \\\\ 0 & 0 & 0 \\\\ \\frac{1}{2} & 0 & -\\frac{1}{2} \\end{pmatrix}$。方程组 $A^*\\boldsymbol{x} = \\boldsymbol{0}$ 等价于 $x_1 - x_3 = 0$，故全部解为 $\\boldsymbol{x} = k_1(1,0,1)^T + k_2(0,1,0)^T$（$k_1, k_2$ 为任意常数）。\n（3）$A + A^* = \\begin{pmatrix} -\\frac{1}{2} & \\frac{\\sqrt{2}}{2} & \\frac{1}{2} \\\\ \\frac{\\sqrt{2}}{2} & 0 & \\frac{\\sqrt{2}}{2} \\\\ \\frac{1}{2} & \\frac{\\sqrt{2}}{2} & -\\frac{1}{2} \\end{pmatrix}$。计算特征多项式 $|\\lambda E - (A+A^*)| = (\\lambda - 1)(\\lambda + 1)^2$，特征值为 $1, -1, -1$。分别求单位正交特征向量：\n对应 $\\lambda_1 = 1$：$\\boldsymbol{\\eta}_1 = \\left(\\frac{1}{2}, \\frac{\\sqrt{2}}{2}, \\frac{1}{2}\\right)^T$；\n对应 $\\lambda_2 = \\lambda_3 = -1$：取正交单位向量 $\\boldsymbol{\\eta}_2 = \\left(\\frac{1}{2}, -\\frac{\\sqrt{2}}{2}, \\frac{1}{2}\\right)^T$，$\\boldsymbol{\\eta}_3 = \\left(\\frac{\\sqrt{2}}{2}, 0, -\\frac{\\sqrt{2}}{2}\\right)^T$。\n令 $C = (\\boldsymbol{\\eta}_1, \\boldsymbol{\\eta}_2, \\boldsymbol{\\eta}_3) = \\begin{pmatrix} \\frac{1}{2} & \\frac{1}{2} & \\frac{\\sqrt{2}}{2} \\\\ \\frac{\\sqrt{2}}{2} & -\\frac{\\sqrt{2}}{2} & 0 \\\\ \\frac{1}{2} & \\frac{1}{2} & -\\frac{\\sqrt{2}}{2} \\end{pmatrix}$，则 $C^T(A + A^*)C = \\begin{pmatrix} 1 & 0 & 0 \\\\ 0 & -1 & 0 \\\\ 0 & 0 & -1 \\end{pmatrix}$。",
