      "分别求出 $\\lambda=3$ 和 $\\lambda=-3$ 对应的特征向量并正交单位化。",
      "组装正交矩阵 $Q$ 并写出正交变换 $\\boldsymbol{x} = Q\\boldsymbol{y}$。"
