    "question": "已知二次型 $f(x_1, x_2, x_3) = x_1^2 + 2x_2^2 + a x_3^2 + 2x_1x_3$ 经可逆线性变换 $X = PY$ 化为 $y_1^2 + y_3^2$。\n（I）求 $a$ 的值及可逆矩阵 $P$；\n（II）当 $X = (x_1, x_2, x_3)^T$ 且 $X^T X = 1$ 时，求 $f(x_1, x_2, x_3)$ 的最大值，并求满足 $x_1 = x_2 > 0$ 的最大值点。",
