    "correctAnswer": "（I）$Q = \\begin{pmatrix} \\frac{1}{\\sqrt{2}} & \\frac{1}{\\sqrt{6}} & \\frac{1}{\\sqrt{3}} \\\\ -\\frac{1}{\\sqrt{2}} & \\frac{1}{\\sqrt{6}} & \\frac{1}{\\sqrt{3}} \\\\ 0 & -\\frac{2}{\\sqrt{6}} & \\frac{1}{\\sqrt{3}} \\end{pmatrix}$，$\\Lambda = \\mathrm{diag}(1, 1, 0)$；（II）$P = \\begin{pmatrix} \\frac{1}{\\sqrt{2}} & -\\frac{1}{\\sqrt{2}} & 0 \\\\ \\frac{1}{\\sqrt{6}} & \\frac{1}{\\sqrt{6}} & -\\frac{2}{\\sqrt{6}} \\\\ \\frac{\\sqrt{2}}{\\sqrt{3}} & \\frac{\\sqrt{2}}{\\sqrt{3}} & \\frac{\\sqrt{2}}{\\sqrt{3}} \\end{pmatrix}$（不唯一）",
    "explanation": "（I）由 $A^T = A$ 及每列元素和为 $0$ 知 $A$ 的每行元素和也为 $0$，即 $A(1, 1, 1)^T = \\boldsymbol{0}$，故 $\\lambda_3 = 0$，对应单位特征向量为 $\\boldsymbol{\\eta}_3 = \\frac{1}{\\sqrt{3}}(1, 1, 1)^T$。由实对称矩阵不同特征值特征向量正交，属于 $\\lambda_1 = \\lambda_2 = 1$ 的特征向量满足 $x_1 + x_2 + x_3 = 0$，取正交单位向量 $\\boldsymbol{\\eta}_1 = \\frac{1}{\\sqrt{2}}(1, -1, 0)^T$，$\\boldsymbol{\\eta}_2 = \\frac{1}{\\sqrt{6}}(1, 1, -2)^T$。令 $Q = (\\boldsymbol{\\eta}_1, \\boldsymbol{\\eta}_2, \\boldsymbol{\\eta}_3)$，则 $Q^T A Q = \\Lambda = \\mathrm{diag}(1, 1, 0)$。\n（II）$A = 2E - P^T P \\Leftrightarrow P^T P = 2E - A$。由（I）知 $Q^T(2E - A)Q = 2E - \\Lambda = \\mathrm{diag}(1, 1, 2)$。令 $D = \\mathrm{diag}(1, 1, \\sqrt{2})$，则 $2E - A = Q D^2 Q^T = (D Q^T)^T(D Q^T)$。故可取可逆矩阵 $P = D Q^T = \\begin{pmatrix} \\frac{1}{\\sqrt{2}} & -\\frac{1}{\\sqrt{2}} & 0 \\\\ \\frac{1}{\\sqrt{6}} & \\frac{1}{\\sqrt{6}} & -\\frac{2}{\\sqrt{6}} \\\\ \\frac{\\sqrt{2}}{\\sqrt{3}} & \\frac{\\sqrt{2}}{\\sqrt{3}} & \\frac{\\sqrt{2}}{\\sqrt{3}} \\end{pmatrix}$。",
